import{_ as l}from"./plugin-vue_export-helper.21dcd24c.js";import{o as i,c as r,d as e}from"./app.c73131c6.js";const a={},o=e('<h1 id="claude-\u7684-skill-creator-\u6084\u6084\u5347\u7EA7\u4E86-\u8FD9\u6B21\u771F\u6B63\u91CD\u8981\u7684\u4E0D\u662F-\u66F4\u4F1A\u751F\u6210-\u800C\u662F-\u7EC8\u4E8E\u4F1A\u8BC4\u4F30\u4E86" tabindex="-1"><a class="header-anchor" href="#claude-\u7684-skill-creator-\u6084\u6084\u5347\u7EA7\u4E86-\u8FD9\u6B21\u771F\u6B63\u91CD\u8981\u7684\u4E0D\u662F-\u66F4\u4F1A\u751F\u6210-\u800C\u662F-\u7EC8\u4E8E\u4F1A\u8BC4\u4F30\u4E86" aria-hidden="true">#</a> Claude \u7684 Skill-creator \u6084\u6084\u5347\u7EA7\u4E86\uFF1A\u8FD9\u6B21\u771F\u6B63\u91CD\u8981\u7684\u4E0D\u662F\u201C\u66F4\u4F1A\u751F\u6210\u201D\uFF0C\u800C\u662F\u201C\u7EC8\u4E8E\u4F1A\u8BC4\u4F30\u4E86\u201D</h1><p>\u4ECA\u5929\u770B\u4E86\u4E00\u7BC7\u516C\u4F17\u53F7\u6587\u7AE0\uFF0C\u4E3B\u9898\u662F Anthropic \u66F4\u65B0\u4E86 <code>skill-creator</code>\u3002\u6211\u7684\u7ED3\u8BBA\u5F88\u76F4\u63A5\uFF1A<strong>\u5982\u679C\u6587\u7AE0\u63CF\u8FF0\u57FA\u672C\u5C5E\u5B9E\uFF0C\u8FD9\u6B21\u66F4\u65B0\u771F\u6B63\u6709\u4EF7\u503C\u7684\u5730\u65B9\uFF0C\u4E0D\u662F\u53C8\u591A\u4F1A\u5199\u4E00\u70B9 Skill\uFF0C\u800C\u662F\u628A Skills \u4ECE\u201C\u624B\u5DE5\u4F5C\u574A\u201D\u5F80\u201C\u53EF\u91CF\u5316\u8FED\u4EE3\u7684\u5DE5\u7A0B\u4F53\u7CFB\u201D\u63A8\u8FDB\u4E86\u4E00\u5927\u6B65\u3002</strong></p><p>\u5F88\u591A\u4EBA\u770B\u8FD9\u7C7B\u66F4\u65B0\uFF0C\u7B2C\u4E00\u53CD\u5E94\u4F1A\u662F\uFF1A\u201C\u54E6\uFF0C\u751F\u6210\u5668\u66F4\u5F3A\u4E86\u3002\u201D \u4F46\u6211\u89C9\u5F97\u8FD9\u6B21\u66F4\u5173\u952E\u7684\u53D8\u5316\u5176\u5B9E\u662F\uFF1A<strong>Skill-creator \u5F00\u59CB\u8986\u76D6 Skill \u7684\u5B8C\u6574\u751F\u547D\u5468\u671F\u4E86\u3002</strong></p><hr><h2 id="_1-\u65E7\u95EE\u9898\u4E0D\u5728-\u5199\u4E0D\u51FA\u6765-\u800C\u5728-\u4F60\u6839\u672C\u4E0D\u77E5\u9053\u5B83\u597D\u4E0D\u597D" tabindex="-1"><a class="header-anchor" href="#_1-\u65E7\u95EE\u9898\u4E0D\u5728-\u5199\u4E0D\u51FA\u6765-\u800C\u5728-\u4F60\u6839\u672C\u4E0D\u77E5\u9053\u5B83\u597D\u4E0D\u597D" aria-hidden="true">#</a> 1. \u65E7\u95EE\u9898\u4E0D\u5728\u201C\u5199\u4E0D\u51FA\u6765\u201D\uFF0C\u800C\u5728\u201C\u4F60\u6839\u672C\u4E0D\u77E5\u9053\u5B83\u597D\u4E0D\u597D\u201D</h2><p>\u8FC7\u53BB\u5927\u5BB6\u505A Skill\uFF0C\u6700\u5927\u7684\u95EE\u9898\u5F80\u5F80\u4E0D\u662F\u5199\u4E0D\u51FA\u6765\u3002 \u53EA\u8981\u6A21\u578B\u80FD\u529B\u591F\u5F3A\uFF0C\u5F88\u591A Skill \u90FD\u80FD\u5148\u6413\u51FA\u4E00\u4E2A\u80FD\u8DD1\u7684\u7248\u672C\u3002</p><p>\u771F\u6B63\u9EBB\u70E6\u7684\u662F\u540E\u9762\u7684\u4E8B\uFF1A</p><ol><li>\u8FD9\u4E2A Skill \u5230\u5E95\u7A33\u4E0D\u7A33\uFF1F</li><li>\u5B83\u4EC0\u4E48\u65F6\u5019\u8BE5\u89E6\u53D1\uFF0C\u4EC0\u4E48\u65F6\u5019\u4E0D\u8BE5\u89E6\u53D1\uFF1F</li><li>\u548C\u5176\u4ED6\u76F8\u4F3C Skill \u4F1A\u4E0D\u4F1A\u6253\u67B6\uFF1F</li><li>\u5B83\u771F\u7684\u63D0\u5347\u4E86\u4EFB\u52A1\u6210\u529F\u7387\uFF0C\u8FD8\u662F\u53EA\u662F\u770B\u8D77\u6765\u66F4\u806A\u660E\uFF1F</li><li>\u4E3A\u4E86\u7528\u8FD9\u4E2A Skill\uFF0C\u591A\u82B1\u7684 token \u548C\u65F6\u95F4\u5230\u5E95\u503C\u4E0D\u503C\uFF1F</li></ol><p>\u8FD9\u4E5F\u662F\u4E3A\u4EC0\u4E48\u5F88\u591A Agent \u7CFB\u7EDF\u5728\u65E9\u671F\u770B\u8D77\u6765\u5F88\u70ED\u95F9\uFF0CSkill \u8D8A\u88C5\u8D8A\u591A\uFF0C\u4F46\u8D8A\u5230\u540E\u9762\u8D8A\u5BB9\u6613\u5931\u63A7\u3002\u95EE\u9898\u4E0D\u5728\u201C\u6CA1\u6709\u80FD\u529B\u201D\uFF0C\u800C\u5728<strong>\u7F3A\u5C11\u8BC4\u4F30\u673A\u5236\u3001\u7F3A\u5C11\u8FB9\u754C\u7BA1\u7406\u3001\u7F3A\u5C11\u91CF\u5316\u53CD\u9988</strong>\u3002</p><p>\u6240\u4EE5\u4ECE\u8FD9\u4E2A\u89D2\u5EA6\u770B\uFF0C<code>skill-creator</code> \u8FD9\u6B21\u8865\u4E0A\u7684\u4E0D\u662F\u4E00\u4E2A\u5C0F\u529F\u80FD\uFF0C\u800C\u662F\u4E00\u4E2A\u5173\u952E\u7F3A\u53E3\u3002</p><hr><h2 id="_2-\u8FD9\u6B21\u66F4\u65B0\u8865\u4E0A\u7684\u56DB\u4EF6\u4E8B-\u771F\u6B63\u6539\u53D8\u4E86\u4EC0\u4E48" tabindex="-1"><a class="header-anchor" href="#_2-\u8FD9\u6B21\u66F4\u65B0\u8865\u4E0A\u7684\u56DB\u4EF6\u4E8B-\u771F\u6B63\u6539\u53D8\u4E86\u4EC0\u4E48" aria-hidden="true">#</a> 2. \u8FD9\u6B21\u66F4\u65B0\u8865\u4E0A\u7684\u56DB\u4EF6\u4E8B\uFF0C\u771F\u6B63\u6539\u53D8\u4E86\u4EC0\u4E48</h2><p>\u6309\u7167\u6587\u7AE0\u91CC\u7684\u63CF\u8FF0\uFF0C\u8FD9\u6B21\u4E3B\u8981\u65B0\u589E\u4E86\u56DB\u7C7B\u80FD\u529B\uFF1A</p><ol><li><strong>\u8BC4\u4F30\u7CFB\u7EDF</strong>\uFF1A\u505A\u5B8C\u4E4B\u540E\uFF0C\u4E0D\u518D\u53EA\u662F\u201C\u611F\u89C9\u8FD9\u4E2A Skill \u597D\u50CF\u8FD8\u884C\u201D\uFF0C\u800C\u662F\u53EF\u4EE5\u66F4\u7CFB\u7EDF\u5730\u5224\u65AD\u5B83\u5230\u5E95\u884C\u4E0D\u884C\u3002</li><li><strong>\u57FA\u51C6\u6D4B\u8BD5</strong>\uFF1A\u628A\u901A\u8FC7\u7387\u3001\u8017\u65F6\u3001token \u6D88\u8017\u8FD9\u4E9B\u7EF4\u5EA6\u91CF\u5316\u51FA\u6765\uFF0C\u81F3\u5C11\u80FD\u5F00\u59CB\u6BD4\u8F83\u3002</li><li><strong>\u591A\u4EE3\u7406\u5E76\u884C\u6D4B\u8BD5</strong>\uFF1A\u591A\u4E2A\u6D4B\u8BD5\u5728\u76F8\u4E92\u9694\u79BB\u7684\u5E72\u51C0\u73AF\u5883\u4E2D\u72EC\u7ACB\u8FD0\u884C\uFF0C\u51CF\u5C11\u4E0A\u4E0B\u6587\u6C61\u67D3\u3002</li><li><strong>\u63CF\u8FF0\u8C03\u4F18</strong>\uFF1A\u81EA\u52A8\u4F18\u5316 Skill \u7684\u89E6\u53D1\u63CF\u8FF0\uFF0C\u8BA9\u8BE5\u89E6\u53D1\u7684\u89E6\u53D1\uFF0C\u4E0D\u8BE5\u89E6\u53D1\u7684\u522B\u4E71\u8FDB\u6765\u3002</li></ol><p>\u5982\u679C\u53EA\u770B\u5B57\u9762\uFF0C\u8FD9\u50CF\u662F\u56DB\u4E2A\u96F6\u6563\u529F\u80FD\u3002 \u4F46\u5982\u679C\u653E\u5230 Agent \u5DE5\u7A0B\u91CC\u770B\uFF0C\u5176\u5B9E\u8FD9\u56DB\u4E2A\u70B9\u8FDE\u8D77\u6765\u6784\u6210\u4E86\u4E00\u6761\u66F4\u5B8C\u6574\u7684\u94FE\u8DEF\uFF1A</p><p><strong>\u5B9A\u4E49\u8FB9\u754C \u2192 \u6784\u9020\u6837\u672C \u2192 \u8DD1\u8BC4\u4F30 \u2192 \u6BD4\u8F83\u7ED3\u679C \u2192 \u81EA\u52A8\u8C03\u4F18 \u2192 \u56DE\u5199\u914D\u7F6E</strong></p><p>\u8FD9\u6761\u94FE\u8DEF\u4E00\u65E6\u80FD\u987A\u8D77\u6765\uFF0CSkill \u5C31\u4E0D\u518D\u53EA\u662F\u4E00\u4E2A\u201C\u63D0\u793A\u8BCD\u914D\u4EF6\u201D\uFF0C\u800C\u5F00\u59CB\u6709\u70B9\u50CF\u4E00\u4E2A<strong>\u53EF\u6D4B\u8BD5\u3001\u53EF\u56DE\u5F52\u3001\u53EF\u4F18\u5316\u7684\u80FD\u529B\u6A21\u5757</strong>\u3002</p><hr><h2 id="_3-\u6211\u89C9\u5F97\u6700\u503C\u94B1\u7684-\u5176\u5B9E\u662F-\u63CF\u8FF0\u8C03\u4F18" tabindex="-1"><a class="header-anchor" href="#_3-\u6211\u89C9\u5F97\u6700\u503C\u94B1\u7684-\u5176\u5B9E\u662F-\u63CF\u8FF0\u8C03\u4F18" aria-hidden="true">#</a> 3. \u6211\u89C9\u5F97\u6700\u503C\u94B1\u7684\uFF0C\u5176\u5B9E\u662F\u201C\u63CF\u8FF0\u8C03\u4F18\u201D</h2><p>\u6587\u7AE0\u91CC\u6700\u8BA9\u6211\u89C9\u5F97\u5BF9\u5473\u7684\uFF0C\u4E0D\u662F\u201C\u4F1A\u751F\u6210 Skill\u201D\uFF0C\u800C\u662F\u201C\u4F1A\u4F18\u5316\u89E6\u53D1\u63CF\u8FF0\u201D\u3002</p><p>\u8FD9\u662F\u5F88\u591A\u505A Agent \u7684\u4EBA\u6700\u5BB9\u6613\u4F4E\u4F30\u3001\u4F46\u53C8\u6700\u5BB9\u6613\u7FFB\u8F66\u7684\u5730\u65B9\u3002</p><p>\u56E0\u4E3A\u5F88\u591A\u65F6\u5019\uFF0CSkill \u5E76\u4E0D\u662F\u6267\u884C\u903B\u8F91\u6709\u95EE\u9898\uFF0C\u800C\u662F<strong>\u5165\u53E3\u5224\u65AD</strong>\u6709\u95EE\u9898\uFF1A</p><ol><li>\u89E6\u53D1\u6761\u4EF6\u5199\u5F97\u592A\u5BBD\uFF0C\u4EC0\u4E48\u90FD\u60F3\u63A5\uFF1B</li><li>\u89E6\u53D1\u6761\u4EF6\u5199\u5F97\u592A\u7A84\uFF0C\u8BE5\u89E6\u53D1\u7684\u65F6\u5019\u53C8\u4E0D\u8FDB\uFF1B</li><li>\u4E24\u4E2A\u76F8\u4F3C Skill \u90FD\u89C9\u5F97\u201C\u8FD9\u5355\u5E94\u8BE5\u662F\u6211\u7684\u201D\uFF1B</li><li>\u5728\u6A21\u7CCA\u8FB9\u754C\u573A\u666F\u4E0B\uFF0C\u6A21\u578B\u7ECF\u5E38\u968F\u673A\u53D1\u6325\u3002</li></ol><p>\u6587\u7AE0\u63D0\u5230\u7684\u6D41\u7A0B\u662F\uFF1A</p><ol><li>\u5148\u751F\u6210\u201C\u5E94\u8BE5\u89E6\u53D1\u201D\u7684\u6837\u672C\uFF1B</li><li>\u518D\u751F\u6210\u201C\u4E0D\u5E94\u8BE5\u89E6\u53D1\u201D\u7684\u6837\u672C\uFF1B</li><li>\u4EBA\u5DE5\u68C0\u67E5\u8FB9\u754C\u6848\u4F8B\uFF1B</li><li>\u62C6\u5206\u8BAD\u7EC3\u96C6\u548C\u6D4B\u8BD5\u96C6\uFF1B</li><li>\u81EA\u52A8\u8FED\u4EE3\u4F18\u5316\u63CF\u8FF0\uFF1B</li><li>\u7528\u6D4B\u8BD5\u96C6\u8868\u73B0\u6765\u9009\u6700\u4F18\u7248\u672C\uFF0C\u907F\u514D\u8FC7\u62DF\u5408\u3002</li></ol><p>\u8FD9\u4E2A\u601D\u8DEF\u975E\u5E38\u6B63\u786E\u3002</p><p>\u56E0\u4E3A\u771F\u6B63\u8BA9 Agent \u7A33\u5B9A\u4E0B\u6765\u7684\uFF0C\u5F80\u5F80\u4E0D\u662F\u201C\u6BCF\u4E2A Skill \u90FD\u7279\u522B\u5F3A\u201D\uFF0C\u800C\u662F<strong>\u8DEF\u7531\u5C42\u8DB3\u591F\u6E05\u6670</strong>\u3002 \u4E00\u65E6\u8DEF\u7531\u6DF7\u4E71\uFF0C\u518D\u5F3A\u7684 Skill \u4E5F\u4F1A\u88AB\u9519\u8BEF\u5730\u8C03\u7528\uFF1B\u800C\u4E00\u4E2A\u63CF\u8FF0\u8FB9\u754C\u6E05\u6670\u7684\u666E\u901A Skill\uFF0C\u5F80\u5F80\u53CD\u800C\u66F4\u5B9E\u7528\u3002</p><p>\u6362\u53E5\u8BDD\u8BF4\uFF0C<strong>\u8FD9\u6B21\u66F4\u65B0\u6700\u6709\u6F5C\u529B\u6539\u5584\u7684\uFF0C\u4E0D\u662F Skill \u7684\u4E0A\u9650\uFF0C\u800C\u662F\u6574\u4E2A\u7CFB\u7EDF\u7684\u4E0B\u9650\u3002</strong></p><hr><h2 id="_4-\u591A\u4EE3\u7406\u5E76\u884C\u6D4B\u8BD5-\u4EF7\u503C\u4E0D\u53EA\u662F-\u66F4\u5FEB" tabindex="-1"><a class="header-anchor" href="#_4-\u591A\u4EE3\u7406\u5E76\u884C\u6D4B\u8BD5-\u4EF7\u503C\u4E0D\u53EA\u662F-\u66F4\u5FEB" aria-hidden="true">#</a> 4. \u591A\u4EE3\u7406\u5E76\u884C\u6D4B\u8BD5\uFF0C\u4EF7\u503C\u4E0D\u53EA\u662F\u201C\u66F4\u5FEB\u201D</h2><p>\u6587\u7AE0\u8FD8\u63D0\u5230\u4E00\u4E2A\u5F88\u5173\u952E\u7684\u70B9\uFF1A\u6BCF\u4E2A\u6D4B\u8BD5\u5728\u72EC\u7ACB\u3001\u5E72\u51C0\u7684\u73AF\u5883\u91CC\u8DD1\u3002</p><p>\u8FD9\u4EF6\u4E8B\u770B\u8D77\u6765\u53EA\u662F\u5DE5\u7A0B\u7EC6\u8282\uFF0C\u4F46\u5B9E\u9645\u4E0A\u610F\u4E49\u5F88\u5927\u3002</p><p>\u8FC7\u53BB\u5F88\u591A\u6240\u8C13\u201C\u8BC4\u4F30\u201D\uFF0C\u5176\u5B9E\u90FD\u4E0D\u592A\u5E72\u51C0\uFF1A</p><ol><li>\u4EFB\u52A1\u662F\u987A\u5E8F\u8DD1\u7684\uFF1B</li><li>\u524D\u4E00\u4E2A\u6837\u4F8B\u4EA7\u751F\u7684\u4E0A\u4E0B\u6587\uFF0C\u4F1A\u5F71\u54CD\u540E\u4E00\u4E2A\u6837\u4F8B\uFF1B</li><li>\u6A21\u578B\u4E0D\u662F\u5728\u201C\u72EC\u7ACB\u5224\u65AD\u201D\uFF0C\u800C\u662F\u5728\u201C\u5E26\u7740\u5386\u53F2\u8BB0\u5FC6\u7EE7\u7EED\u505A\u9898\u201D\u3002</li></ol><p>\u8FD9\u6837\u5F97\u51FA\u6765\u7684\u7ED3\u679C\u5F88\u5BB9\u6613\u504F\u4E50\u89C2\u3002 \u4F60\u4EE5\u4E3A Skill \u5F88\u5F3A\uFF0C\u53EF\u80FD\u53EA\u662F\u56E0\u4E3A\u4E0A\u4E0B\u6587\u5077\u5077\u5E2E\u4E86\u5FD9\u3002</p><p>\u5982\u679C\u65B0\u7248\u771F\u80FD\u505A\u5230\uFF1A</p><ol><li>\u591A\u4E2A\u5B50\u4EE3\u7406\u72EC\u7ACB\u8FD0\u884C\uFF1B</li><li>\u6BCF\u6B21\u6D4B\u8BD5\u73AF\u5883\u90FD\u5E72\u51C0\u9694\u79BB\uFF1B</li><li>\u5206\u522B\u8BB0\u5F55\u8017\u65F6\u3001token\u3001\u6210\u529F\u7387\uFF1B</li></ol><p>\u90A3\u5B83\u5E26\u6765\u7684\u63D0\u5347\u5C31\u4E0D\u53EA\u662F\u201C\u5E76\u53D1\u66F4\u5FEB\u201D\uFF0C\u800C\u662F<strong>\u8BC4\u4F30\u7ED3\u679C\u66F4\u63A5\u8FD1\u771F\u5B9E\u7528\u6237\u7684\u9996\u6B21\u89E6\u53D1\u573A\u666F</strong>\u3002</p><p>\u8FD9\u5BF9 Skill \u6765\u8BF4\u7279\u522B\u5173\u952E\uFF0C\u56E0\u4E3A\u7528\u6237\u771F\u6B63\u9762\u5BF9\u7684\uFF0C\u5F80\u5F80\u4E0D\u662F\u201C\u5DF2\u7ECF\u88AB\u94FA\u57AB\u597D\u4E0A\u4E0B\u6587\u7684\u7B2C\u5341\u8F6E\u5BF9\u8BDD\u201D\uFF0C\u800C\u662F\u67D0\u4E2A\u7A81\u7136\u51FA\u73B0\u7684\u3001\u4FE1\u606F\u5E76\u4E0D\u5145\u5206\u7684\u771F\u5B9E\u8BF7\u6C42\u3002</p><hr><h2 id="_5-\u4ECE\u6848\u4F8B\u53EF\u4EE5\u770B\u51FA-\u5B83\u60F3\u505A\u7684\u662F-skill-\u7684-\u5168\u751F\u547D\u5468\u671F\u5DE5\u5177" tabindex="-1"><a class="header-anchor" href="#_5-\u4ECE\u6848\u4F8B\u53EF\u4EE5\u770B\u51FA-\u5B83\u60F3\u505A\u7684\u662F-skill-\u7684-\u5168\u751F\u547D\u5468\u671F\u5DE5\u5177" aria-hidden="true">#</a> 5. \u4ECE\u6848\u4F8B\u53EF\u4EE5\u770B\u51FA\uFF1A\u5B83\u60F3\u505A\u7684\u662F Skill \u7684\u201C\u5168\u751F\u547D\u5468\u671F\u5DE5\u5177\u201D</h2><p>\u6587\u7AE0\u91CC\u4E3E\u7684\u4F8B\u5B50\uFF0C\u662F\u505A\u4E00\u4E2A\u201C\u7ED9\u6211\u89C6\u9891\u94FE\u63A5\uFF0C\u8F93\u51FA\u8BB2\u7A3F\uFF1B\u5982\u679C\u662F\u5916\u8BED\uFF0C\u6700\u597D\u7ED9\u6211\u539F\u6587\u548C\u4E2D\u6587\u7248\u672C\u201D\u7684 Skill\u3002</p><p>\u8FD9\u4E2A\u6848\u4F8B\u8868\u9762\u4E0A\u662F\u5728\u5C55\u793A\u751F\u6210\u80FD\u529B\uFF0C\u4F46\u771F\u6B63\u6709\u610F\u601D\u7684\u662F\u5B83\u540E\u9762\u7684\u94FE\u8DEF\uFF1A</p><ol><li>\u5148\u6839\u636E\u81EA\u7136\u8BED\u8A00\u9700\u6C42\u751F\u6210 Skill\uFF1B</li><li>\u53D1\u73B0\u8F93\u51FA\u6392\u7248\u4E0D\u597D\uFF1B</li><li>\u518D\u7EE7\u7EED\u5BF9\u8BDD\u8BA9\u5B83\u6539\u8FDB\uFF1B</li><li>\u53D1\u73B0\u53EF\u80FD\u4F1A\u548C\u53E6\u4E00\u4E2A\u89C6\u9891\u76F8\u5173 Skill \u51B2\u7A81\uFF1B</li><li>\u518D\u56DE\u5934\u505A\u89E6\u53D1\u8BC4\u4F30\u548C\u63CF\u8FF0\u4F18\u5316\uFF1B</li><li>\u6700\u540E\u7EE7\u7EED\u505A benchmark \u548C\u6548\u679C\u9A8C\u8BC1\u3002</li></ol><p>\u8FD9\u4E2A\u6D41\u7A0B\u8BF4\u660E\uFF0C<code>skill-creator</code> \u60F3\u505A\u7684\u5DF2\u7ECF\u4E0D\u662F\u201C\u5E2E\u4F60\u5199\u4E00\u4E2A SKILL.md\u201D\u8FD9\u4E48\u7B80\u5355\uFF0C\u800C\u662F\u60F3\u8986\u76D6\uFF1A</p><ol><li>\u9700\u6C42\u6F84\u6E05</li><li>\u521D\u7248\u751F\u6210</li><li>\u7ED3\u679C\u8C03\u4F18</li><li>\u89E6\u53D1\u8FB9\u754C\u4FEE\u6B63</li><li>\u4EFB\u52A1\u6548\u679C\u8BC4\u4F30</li><li>\u6301\u7EED\u53CD\u9988\u95ED\u73AF</li></ol><p>\u5982\u679C\u8FD9\u4E2A\u65B9\u5411\u7EE7\u7EED\u505A\u4E0B\u53BB\uFF0C\u5B83\u6700\u7EC8\u53EF\u80FD\u4F1A\u4ECE\u4E00\u4E2A\u201CSkill \u751F\u6210\u5668\u201D\u53D8\u6210\u4E00\u4E2A\u66F4\u50CF<strong>Skill IDE / Skill QA \u5DE5\u5177\u94FE</strong>\u7684\u4E1C\u897F\u3002</p><hr><h2 id="_6-\u8FD9\u7BC7\u6587\u7AE0\u4E3A\u4EC0\u4E48\u6709\u542F\u53D1-\u4F46\u4E5F\u4E0D\u80FD\u5168\u4FE1" tabindex="-1"><a class="header-anchor" href="#_6-\u8FD9\u7BC7\u6587\u7AE0\u4E3A\u4EC0\u4E48\u6709\u542F\u53D1-\u4F46\u4E5F\u4E0D\u80FD\u5168\u4FE1" aria-hidden="true">#</a> 6. \u8FD9\u7BC7\u6587\u7AE0\u4E3A\u4EC0\u4E48\u6709\u542F\u53D1\uFF0C\u4F46\u4E5F\u4E0D\u80FD\u5168\u4FE1</h2><p>\u6211\u89C9\u5F97\u8FD9\u7BC7\u6587\u7AE0\u7684\u4EF7\u503C\u662F\u6709\u7684\uFF0C\u4F46\u4E5F\u8981\u5206\u5F00\u770B\u3002</p><h3 id="\u503C\u5F97\u80AF\u5B9A\u7684\u5730\u65B9" tabindex="-1"><a class="header-anchor" href="#\u503C\u5F97\u80AF\u5B9A\u7684\u5730\u65B9" aria-hidden="true">#</a> \u503C\u5F97\u80AF\u5B9A\u7684\u5730\u65B9</h3><ol><li>\u5B83\u6293\u4F4F\u4E86\u4E00\u4E2A\u771F\u95EE\u9898\uFF1ASkill \u7684\u6838\u5FC3\u96BE\u70B9\u5DF2\u7ECF\u4E0D\u662F\u201C\u5199\u51FA\u6765\u201D\uFF0C\u800C\u662F\u201C\u9A8C\u8BC1\u548C\u8FED\u4EE3\u201D\u3002</li><li>\u5B83\u628A\u201C\u8BC4\u4F30\u201D\u653E\u5728\u4E2D\u5FC3\u4F4D\u7F6E\uFF0C\u8FD9\u4E2A\u5224\u65AD\u662F\u5BF9\u7684\u3002</li><li>\u5B83\u7ED9\u51FA\u7684\u4F8B\u5B50\u8DB3\u591F\u8D34\u8FD1\u771F\u5B9E\u4F7F\u7528\u573A\u666F\uFF0C\u4E0D\u662F\u7EAF\u6982\u5FF5\u5C55\u793A\u3002</li></ol><h3 id="\u9700\u8981\u4FDD\u7559\u5224\u65AD\u7684\u5730\u65B9" tabindex="-1"><a class="header-anchor" href="#\u9700\u8981\u4FDD\u7559\u5224\u65AD\u7684\u5730\u65B9" aria-hidden="true">#</a> \u9700\u8981\u4FDD\u7559\u5224\u65AD\u7684\u5730\u65B9</h3><ol><li>\u6587\u98CE\u660E\u663E\u504F\u5174\u594B\u548C\u5BA3\u4F20\uFF0C\u50CF\u201C\u53F2\u8BD7\u7EA7\u5347\u7EA7\u201D\u201C\u7279\u522B\u725B\u201D\u201C\u60CA\u5446\u4E86\u201D\u8FD9\u7C7B\u8868\u8FBE\u5F88\u591A\uFF1B</li><li>\u867D\u7136\u63D0\u5230\u4E86 benchmark\u3001\u901A\u8FC7\u7387\u3001token \u6D88\u8017\uFF0C\u4F46\u4ECE\u6587\u7AE0\u5185\u5BB9\u672C\u8EAB\u6765\u770B\uFF0C\u91CF\u5316\u53E3\u5F84\u8FD8\u4E0D\u591F\u4E25\u8C28\uFF1B</li><li>\u67D0\u4E9B\u6570\u636E\u770B\u8D77\u6765\u5F88\u4EAE\u773C\uFF0C\u4F46\u8FD8\u7F3A\u5C11\u66F4\u591A\u53EF\u590D\u73B0\u7684\u80CC\u666F\u8BF4\u660E\uFF0C\u6BD4\u5982\u4EFB\u52A1\u5B9A\u4E49\u3001\u6837\u672C\u89C4\u6A21\u3001\u4EFB\u52A1\u5206\u5E03\u3001\u8BC4\u4F30\u6807\u51C6\u7B49\u3002</li></ol><p>\u6240\u4EE5\u6211\u7684\u5224\u65AD\u662F\uFF1A</p><p><strong>\u65B9\u5411\u5F88\u503C\u5F97\u91CD\u89C6\uFF0C\u4F46\u7ED3\u8BBA\u6682\u65F6\u66F4\u9002\u5408\u5F53\u201C\u9AD8\u4EF7\u503C\u7EBF\u7D22\u201D\uFF0C\u4E0D\u9002\u5408\u76F4\u63A5\u5F53\u201C\u5DF2\u7ECF\u88AB\u5145\u5206\u8BC1\u660E\u7684\u4E8B\u5B9E\u201D\u3002</strong></p><p>\u4E5F\u5C31\u662F\u8BF4\uFF0C\u8FD9\u4E0D\u662F\u4E00\u7BC7\u5E94\u8BE5\u65E0\u8111\u7167\u5355\u5168\u6536\u7684\u6587\u7AE0\uFF0C\u4F46\u5B83\u786E\u5B9E\u6307\u51FA\u4E86\u4E00\u4E2A\u975E\u5E38\u503C\u5F97\u8DDF\u8FDB\u7684\u8D8B\u52BF\u3002</p><hr><h2 id="_7-\u5982\u679C\u653E\u5230-openclaw-\u81EA\u5EFA-agent-\u4F53\u7CFB\u91CC-\u8FD9\u610F\u5473\u7740\u4EC0\u4E48" tabindex="-1"><a class="header-anchor" href="#_7-\u5982\u679C\u653E\u5230-openclaw-\u81EA\u5EFA-agent-\u4F53\u7CFB\u91CC-\u8FD9\u610F\u5473\u7740\u4EC0\u4E48" aria-hidden="true">#</a> 7. \u5982\u679C\u653E\u5230 OpenClaw / \u81EA\u5EFA Agent \u4F53\u7CFB\u91CC\uFF0C\u8FD9\u610F\u5473\u7740\u4EC0\u4E48</h2><p>\u5982\u679C\u4F60\u672C\u6765\u5C31\u5728\u505A OpenClaw\u3001Claude Code\u3001Codex \u8FD9\u7C7B Agent \u4F53\u7CFB\uFF0C\u90A3\u8FD9\u6B21\u66F4\u65B0\u771F\u6B63\u503C\u5F97\u5B66\u7684\uFF0C\u53EF\u80FD\u4E0D\u662F\u67D0\u4E2A\u5177\u4F53\u6309\u94AE\uFF0C\u800C\u662F\u4E0B\u9762\u8FD9\u4E9B\u65B9\u6CD5\u8BBA\uFF1A</p><ol><li><strong>Skill \u9700\u8981\u660E\u786E\u8FB9\u754C\uFF0C\u800C\u4E0D\u662F\u6A21\u7CCA\u529F\u80FD\u63CF\u8FF0\u3002</strong></li><li><strong>\u5FC5\u987B\u6709 negative cases\u3002</strong> \u4E0D\u662F\u53EA\u6D4B\u201C\u4EC0\u4E48\u65F6\u5019\u8BE5\u89E6\u53D1\u201D\uFF0C\u8FD8\u8981\u6D4B\u201C\u4EC0\u4E48\u65F6\u5019\u4E0D\u8BE5\u89E6\u53D1\u201D\u3002</li><li><strong>\u8BC4\u4F30\u5FC5\u987B\u5C3D\u91CF\u9694\u79BB\u4E0A\u4E0B\u6587\u6C61\u67D3\u3002</strong> \u987A\u5E8F\u8DD1\u51FA\u6765\u7684\u6F02\u4EAE\u7ED3\u679C\uFF0C\u7ECF\u5E38\u4E0D\u53EF\u9760\u3002</li><li><strong>\u4E0D\u8981\u53EA\u770B\u80FD\u4E0D\u80FD\u505A\u51FA\u6765\uFF0C\u8FD8\u8981\u770B\u6210\u529F\u7387\u3001\u8017\u65F6\u548C token \u6210\u672C\u3002</strong></li><li><strong>\u4F18\u5316 description \u7684\u6536\u76CA\uFF0C\u6709\u65F6\u6BD4\u4F18\u5316\u6267\u884C\u903B\u8F91\u8FD8\u5927\u3002</strong></li></ol><p>\u8FD9\u51E0\u4E2A\u70B9\u5176\u5B9E\u5F88\u5DE5\u7A0B\u5316\uFF0C\u4E5F\u5F88\u73B0\u5B9E\u3002</p><p>\u5F88\u591A Agent \u7CFB\u7EDF\u6700\u540E\u4E0D\u7A33\u5B9A\uFF0C\u4E0D\u662F\u8D25\u5728\u6A21\u578B\u4E0D\u591F\u5F3A\uFF0C\u800C\u662F\u8D25\u5728\uFF1A</p><ol><li>\u8DEF\u7531\u6DF7\u4E71\uFF1B</li><li>\u8FB9\u754C\u4E0D\u6E05\uFF1B</li><li>\u6CA1\u6709\u7EDF\u4E00\u8BC4\u4F30\uFF1B</li><li>\u8C03\u4F18\u5168\u9760\u4F53\u611F\u3002</li></ol><p>\u4ECE\u8FD9\u4E2A\u89D2\u5EA6\u770B\uFF0C<code>skill-creator</code> \u8FD9\u6B21\u66F4\u65B0\u6700\u503C\u5F97\u5173\u6CE8\u7684\uFF0C\u4E0D\u662F\u201C\u591A\u4E86\u51E0\u4E2A\u529F\u80FD\u201D\uFF0C\u800C\u662F\u5B83\u5F00\u59CB\u628A Skills \u8FD9\u4EF6\u4E8B\u62C9\u5411\u4E00\u5957\u66F4\u50CF\u8F6F\u4EF6\u5DE5\u7A0B\u7684\u6D41\u7A0B\u3002</p><hr><h2 id="_8-\u6211\u7684\u603B\u8BC4" tabindex="-1"><a class="header-anchor" href="#_8-\u6211\u7684\u603B\u8BC4" aria-hidden="true">#</a> 8. \u6211\u7684\u603B\u8BC4</h2><p>\u5982\u679C\u53EA\u7528\u4E00\u53E5\u8BDD\u603B\u7ED3\u8FD9\u6B21\u66F4\u65B0\uFF0C\u6211\u4F1A\u8FD9\u4E48\u8BF4\uFF1A</p><blockquote><p><strong>Skill-creator \u771F\u6B63\u7684\u5347\u7EA7\uFF0C\u4E0D\u662F\u66F4\u4F1A\u751F\u6210 Skill\uFF0C\u800C\u662F\u7EC8\u4E8E\u5F00\u59CB\u8BA9 Skill \u53D8\u5F97\u53EF\u6D4B\u91CF\u3001\u53EF\u6BD4\u8F83\u3001\u53EF\u8C03\u4F18\u3002</strong></p></blockquote><p>\u5982\u679C\u8FD9\u6761\u8DEF\u7EE7\u7EED\u8D70\u4E0B\u53BB\uFF0C\u672A\u6765\u597D\u7684 Skill \u751F\u6001\uFF0C\u6BD4\u62FC\u7684\u5C31\u4E0D\u518D\u53EA\u662F\u201C\u8C01\u66F4\u4F1A\u5199 Prompt\u201D\uFF0C\u800C\u662F\uFF1A</p><ol><li>\u8C01\u66F4\u4F1A\u5B9A\u4E49\u8FB9\u754C\uFF1B</li><li>\u8C01\u66F4\u4F1A\u8BBE\u8BA1\u8BC4\u4F30\uFF1B</li><li>\u8C01\u66F4\u80FD\u628A\u80FD\u529B\u8DEF\u7531\u3001\u4EFB\u52A1\u6267\u884C\u548C\u53CD\u9988\u95ED\u73AF\u505A\u6210\u4E00\u4E2A\u7A33\u5B9A\u7CFB\u7EDF\u3002</li></ol><p>\u8FD9\u6BD4\u5355\u7EAF\u201C\u518D\u9020\u51E0\u4E2A\u65B0 Skill\u201D\u91CD\u8981\u5F97\u591A\u3002</p><hr><h2 id="_9-\u6700\u540E\u4E00\u53E5" tabindex="-1"><a class="header-anchor" href="#_9-\u6700\u540E\u4E00\u53E5" aria-hidden="true">#</a> 9. \u6700\u540E\u4E00\u53E5</h2><p>\u8FD9\u7BC7\u6587\u7AE0\u6700\u503C\u5F97\u8BB0\u4F4F\u7684\uFF0C\u4E0D\u662F\u201C\u65B0\u7248\u5F88\u5F3A\u201D\uFF0C\u800C\u662F\u8FD9\u80CC\u540E\u7684\u4FE1\u53F7\uFF1A</p><p><strong>Agent \u65F6\u4EE3\u7684\u80FD\u529B\u5EFA\u8BBE\uFF0C\u6B63\u5728\u4ECE\u201C\u521B\u4F5C\u80FD\u529B\u201D\u8F6C\u5411\u201C\u8BC4\u4F30\u80FD\u529B\u201D\u3002</strong></p><p>\u5F53\u4E00\u4E2A\u751F\u6001\u5F00\u59CB\u8BA4\u771F\u505A\u8BC4\u4F30\uFF0C\u5B83\u624D\u7B97\u771F\u6B63\u5F00\u59CB\u6210\u719F\u3002</p>',77),t=[o];function n(s,p){return i(),r("div",null,t)}var c=l(a,[["render",n],["__file","skill-creator-2026-analysis.html.vue"]]);export{c as default};
